<template>
  <section class="group-room" aria-label="旅行群聊">
    <header><div><strong>{{title || `旅行群聊 #${travelId}`}}</strong><small>同行群聊 · 仅已加入的成员可见</small></div><button :disabled="sending" @click="leave">退出群聊</button></header>
    <p v-if="error" class="feedback" role="alert">{{error}} <button v-if="!forbidden" @click="refresh(true)">重试</button></p>
    <div class="history" ref="historyRef" @scroll="onScroll"><button v-if="hasOlder && !forbidden" :disabled="loadingOlder" class="older" @click="loadOlder">{{loadingOlder?'加载中…':'加载更早消息'}}</button><p v-if="!rows.length&&!error" class="empty">还没有消息，向同行者打个招呼吧。</p><div v-for="m in rows" :key="m.id" class="message" :class="{mine:m.senderId===myId}"><UserAvatar :user-id="m.senderId" :avatar="m.avatar" :name="m.nickname||m.username||'同行者'" :size="31"/><div><small>{{m.nickname||m.username||'同行者'}}</small><p>{{m.body}}</p><time>{{m.createdAt}}</time></div></div></div>
    <form v-if="!forbidden" @submit.prevent="send"><label class="sr-only" :for="`group-draft-${travelId}`">发送群聊消息</label><textarea :id="`group-draft-${travelId}`" v-model="draft" maxlength="1000" placeholder="和同行者聊聊…（Enter 发送，Shift+Enter 换行）" @keydown.enter.exact.prevent="send"/><div><span>{{draft.length}} / 1000</span><button :disabled="sending||!draft.trim()">{{sending?'发送中…':'发送'}}</button></div></form>
  </section>
</template>
<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import UserAvatar from './UserAvatar.vue'
import {groupMessages,groupSend,groupRead,groupLeave,type HubMessage} from '@/api/socialHub'
const props=defineProps<{travelId:number;title?:string;refreshKey?:number}>(),emit=defineEmits<{changed:[];left:[]}>()
let me:{id?:number}={};try{me=JSON.parse(localStorage.getItem('travel_user')||'{}')}catch{}
const myId=Number(me.id||0),rows=ref<HubMessage[]>([]),draft=ref(''),error=ref(''),forbidden=ref(false),sending=ref(false),hasOlder=ref(false),loadingOlder=ref(false),historyRef=ref<HTMLElement|null>(null)
let generation=0,disposed=false,inFlight=false,lastRead=0,clientId='',retryBody='',readInFlight=false
async function checked<T>(p:Promise<{code:number;message:string;data:T}>){const r=await p;if(r.code!==200)throw Object.assign(new Error(r.message),{code:r.code});return r.data}
function report(e:unknown){error.value=e instanceof Error?e.message:'操作失败';if((e as {code?:number}).code===403){forbidden.value=true;rows.value=[];emit('changed')}}
function atBottom(){const el=historyRef.value;return !el||el.scrollHeight-el.scrollTop-el.clientHeight<80}
async function markRead(){if(readInFlight||forbidden.value||document.hidden||!atBottom())return;const through=rows.value.at(-1)?.id||0;if(through<=lastRead)return;const g=generation,trip=props.travelId;readInFlight=true;try{await checked(groupRead(trip,through));if(g===generation){lastRead=through;emit('changed')}}catch(e){if(g===generation)report(e)}finally{readInFlight=false}}
function onScroll(){if(atBottom())void markRead()}
async function refresh(force=false){if(inFlight||forbidden.value||document.hidden)return;const g=generation,trip=props.travelId,follow=force||atBottom();inFlight=true;try{const data=await checked(groupMessages(trip));if(g!==generation||disposed)return;const known=new Set(rows.value.map(m=>m.id));if(force||!rows.value.length){rows.value=data.slice().reverse();hasOlder.value=data.length===60}else{rows.value=[...rows.value,...data.filter(m=>!known.has(m.id))].sort((a,b)=>a.id-b.id)}error.value='';await nextTick();if(follow&&historyRef.value)historyRef.value.scrollTop=historyRef.value.scrollHeight;await markRead()}catch(e){if(g===generation&&!disposed)report(e)}finally{inFlight=false}}
async function loadOlder(){const first=rows.value[0];if(!first||loadingOlder.value)return;loadingOlder.value=true;const g=generation,el=historyRef.value,height=el?.scrollHeight||0;try{const data=await checked(groupMessages(props.travelId,first.id));if(g!==generation||disposed)return;rows.value=[...data.reverse(),...rows.value];hasOlder.value=data.length===60;await nextTick();if(el)el.scrollTop=el.scrollHeight-height}catch(e){if(g===generation)report(e)}finally{loadingOlder.value=false}}
async function send(){if(sending.value||forbidden.value||!draft.value.trim())return;const trip=props.travelId,g=generation,text=draft.value.trim();sending.value=true;if(retryBody!==text||!clientId){clientId=crypto.randomUUID();retryBody=text}try{await checked(groupSend(trip,text,clientId));if(g!==generation||disposed)return;draft.value='';clientId='';retryBody='';await refresh(true);emit('changed')}catch(e){if(g===generation)report(e)}finally{sending.value=false}}
async function leave(){if(!confirm('退出后无法继续查看或发送群消息，历史记录保留；重新加入需邀请。确定退出？'))return;try{await checked(groupLeave(props.travelId));rows.value=[];forbidden.value=true;emit('left');emit('changed')}catch(e){report(e)}}
watch(()=>props.travelId,()=>{generation++;rows.value=[];draft.value='';error.value='';forbidden.value=false;lastRead=0;clientId='';retryBody='';void refresh(true)},{immediate:true})
watch(()=>props.refreshKey,()=>void refresh())
function visible(){if(!document.hidden)void refresh()}
onMounted(()=>document.addEventListener('visibilitychange',visible));onBeforeUnmount(()=>{disposed=true;generation++;document.removeEventListener('visibilitychange',visible)})
</script>
<style scoped>
.group-room{display:flex;flex-direction:column;min-width:0;min-height:0;color:#85506d}.group-room header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 22px;border-bottom:1px solid #f1dce7}.group-room header small{display:block;color:#ae869b;font-size:11px;margin-top:5px}.group-room button{border:0;padding:9px 13px;border-radius:12px;background:#f9deeb;color:#985b7c;cursor:pointer}.group-room button:disabled{opacity:.5}.history{flex:1;min-height:0;overflow:auto;padding:20px;background:linear-gradient(#fff9fc,#fff0f7)}.message{display:flex;align-items:flex-start;gap:9px;margin:16px 0}.message.mine{flex-direction:row-reverse}.message>div{max-width:80%;min-width:0}.message small,.message time{display:block;font-size:10px;color:#b08a9e}.message p{margin:5px 0;padding:11px 15px;background:white;border-radius:16px;font-size:14px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;box-shadow:0 3px 10px #ba8ba21a}.message.mine p{background:#ffdeec}.mine small,.mine time{text-align:right}form{padding:14px;background:#fffbfd}textarea{box-sizing:border-box;width:100%;resize:vertical;min-height:72px;max-height:160px;border:0;background:transparent;font:inherit;outline:none;color:#84516d}form>div{display:flex;align-items:center;justify-content:space-between}form span{color:#b18b9f;font-size:11px}.feedback{font-size:13px;padding:10px 18px;margin:0;background:#ffe8f1}.empty{text-align:center;font-size:13px;color:#b08a9e;margin:30px 0}.older{display:block;margin:auto}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:650px){.group-room header{padding:13px}.history{padding:12px}}
</style>
